<script setup>
import { computed } from 'vue'; import { useRouter } from 'vue-router'; import StatCard from '../components/StatCard.vue'; import { getCategoryStats } from '../utils/statistics'; import { getStrongTopics, getWeakTopics, getWrongQuestions } from '../utils/quizEngine'
const router=useRouter(); const stats=computed(()=>getCategoryStats('Onkologi Radiasi')); const strong=computed(()=>getStrongTopics('Onkologi Radiasi')[0]?.topic||'Belum ada data'); const weak=computed(()=>getWeakTopics('Onkologi Radiasi')[0]?.topic||'Radiobiologi'); const wrong=computed(()=>getWrongQuestions().filter(q=>q.kategori==='Onkologi Radiasi').length)
const start=()=>router.push('/daily?category=Onkologi Radiasi')
</script>
<template><section class="page oncology-page"><div class="hero"><div><span class="eyebrow">Prioritas seleksi spesialis</span><h1>Onkologi Radiasi</h1><p>Fokus pada radiobiologi, fisika radiasi, prinsip radioterapi, kasus klinis, toksisitas, paliatif, emergensi, dan komunikasi pasien kanker.</p></div><button class="btn xl" @click="start">Latihan Onkologi Radiasi 50 Soal</button></div><div class="stat-grid"><StatCard title="Dikerjakan" :value="stats.answered"/><StatCard title="Akurasi" :value="`${stats.accuracy}%`"/><StatCard title="Topik terkuat" :value="strong" tone="green"/><StatCard title="Topik terlemah" :value="weak" tone="amber"/><StatCard title="Soal salah untuk diulang" :value="wrong" tone="purple"/></div><div class="card"><h2>Mode khusus Onkologi Radiasi</h2><div class="button-grid"><button class="btn" @click="start">Latihan Radiobiologi</button><button class="btn" @click="start">Latihan Fisika Radiasi</button><button class="btn" @click="start">Latihan Kasus Klinis</button><button class="btn" @click="start">Latihan Efek Samping Radioterapi</button><button class="btn ghost" @click="start">Flash Review</button><button class="btn ghost" @click="start">Topik Lemah: {{ weak }}</button><button class="btn ghost" @click="start">Ulangi Soal Salah</button><button class="btn success" @click="start">Simulasi Ujian Spesialis</button></div></div><div class="card"><h2>Rekomendasi ulang</h2><p>Ulangi topik <strong>{{ weak }}</strong> dan tinjau pembahasan soal salah sebelum mencoba simulasi spesialis.</p></div></section></template>
